// Generated by "npm run build:sql" from supabase/migrations/. Do not edit by hand.
// This is what the app shows, with a Copy button, when the database is behind.
// It is safe to run more than once.
export const requiredSchemaVersion = 4;

export const schemaUpdateSql = "-- TC Assistant database setup (generated by \"npm run build:sql\": edit supabase/migrations/ instead).\n-- Paste this whole file into Supabase: SQL Editor > New query > Run.\n-- It is safe to run more than once, on a new or an existing project.\n\n-- ===== 0001_initial.sql =====\n-- 0001: the tables the app launched with (people, transactions, tasks, documents,\n-- email drafts, settings, templates), each with a user_id column and a lock (row\n-- level security) so a login can only see and change its own rows.\n-- Safe to run more than once.\n\ncreate table if not exists public.people (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,\n  name       text not null,\n  email      text not null,\n  phone      text not null default '',\n  role       text not null check (role in ('client', 'agent')),\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists public.transactions (\n  id               uuid primary key default gen_random_uuid(),\n  user_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,\n  type             text not null check (type in ('buyer', 'seller')),\n  status           text not null default 'active'\n                   check (status in ('active', 'pending', 'closed', 'cancelled')),\n  property_address text not null,\n  client_id        uuid not null references public.people (id),\n  agent_id         uuid not null references public.people (id),\n  contract_date    date,\n  closing_date     date,\n  price            numeric,\n  notes            text not null default '',\n  created_at       date not null default current_date,\n  archived         boolean not null default false\n);\n\ncreate table if not exists public.tasks (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,\n  transaction_id uuid not null references public.transactions (id) on delete cascade,\n  title          text not null,\n  due_date       date,\n  status         text not null default 'open' check (status in ('open', 'done', 'skipped')),\n  key            text,\n  category       text\n);\n\ncreate table if not exists public.documents (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,\n  transaction_id uuid not null references public.transactions (id) on delete cascade,\n  name           text not null,\n  required       boolean not null default true,\n  status         text not null default 'needed' check (status in ('needed', 'requested', 'received')),\n  due_date       date\n);\n\ncreate table if not exists public.email_drafts (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,\n  transaction_id uuid not null references public.transactions (id) on delete cascade,\n  recipient_id   uuid references public.people (id),\n  recipient_email text,\n  kind           text not null check (kind in ('welcome', 'follow-up', 'ai')),\n  subject        text not null,\n  body           text not null,\n  status         text not null default 'draft' check (status in ('draft', 'approved', 'sent')),\n  created_at     timestamptz not null default now(),\n  sent_at        timestamptz,\n  ai_info        jsonb\n);\n\ncreate table if not exists public.settings (\n  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,\n  name    text not null default '',\n  title   text not null default 'Transaction Coordinator',\n  company text not null default '',\n  default_transaction_type text not null default 'buyer'\n                           check (default_transaction_type in ('buyer', 'seller')),\n  follow_up_days integer not null default 7,\n  task_categories jsonb\n);\n\n-- Your edited checklists and email wording, one row per account.\ncreate table if not exists public.templates (\n  user_id    uuid primary key default auth.uid() references auth.users (id) on delete cascade,\n  checklists jsonb not null,\n  emails     jsonb not null\n);\n\n-- Columns added after the first release. On a database made earlier these\n-- add what is missing; on a new one they do nothing.\nalter table public.transactions add column if not exists archived boolean not null default false;\nalter table public.tasks add column if not exists category text;\nalter table public.email_drafts add column if not exists recipient_email text;\nalter table public.settings add column if not exists default_transaction_type text not null default 'buyer'\n  check (default_transaction_type in ('buyer', 'seller'));\nalter table public.settings add column if not exists follow_up_days integer not null default 7;\nalter table public.settings add column if not exists task_categories jsonb;\n\n-- AI drafting: a new kind of draft, the information it was written from, and\n-- drafts for people who aren't saved on the deal (a lender, a title officer).\nalter table public.email_drafts add column if not exists ai_info jsonb;\nalter table public.email_drafts alter column recipient_id drop not null;\nalter table public.email_drafts drop constraint if exists email_drafts_kind_check;\nalter table public.email_drafts add constraint email_drafts_kind_check\n  check (kind in ('welcome', 'follow-up', 'ai'));\n\n-- Indexes: make \"all tasks for this deal\" style lookups fast.\ncreate index if not exists transactions_user_idx on public.transactions (user_id);\ncreate index if not exists people_user_idx       on public.people (user_id);\ncreate index if not exists tasks_transaction_idx on public.tasks (transaction_id);\ncreate index if not exists documents_transaction_idx on public.documents (transaction_id);\ncreate index if not exists drafts_transaction_idx on public.email_drafts (transaction_id);\n\n-- The locks: signed-in users can only touch rows where user_id is their own.\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['people', 'transactions', 'tasks', 'documents', 'email_drafts', 'settings', 'templates']\n  loop\n    execute format('alter table public.%I enable row level security', t);\n    execute format('drop policy if exists \"own rows\" on public.%I', t);\n    execute format(\n      'create policy \"own rows\" on public.%I for all to authenticated\n         using (user_id = (select auth.uid()))\n         with check (user_id = (select auth.uid()))', t);\n  end loop;\nend $$;\n\n-- Make Supabase notice the new tables and columns right away.\nnotify pgrst, 'reload schema';\n\n-- ===== 0002_security_hardening.sql =====\n-- 0002: security hardening. Safe to run more than once.\n--\n--  1. Only signed-in users can touch the tables at all (the anonymous role gets nothing).\n--  2. A record can only point at records of the SAME account. Before this, a row\n--     was locked to its owner, but a task could still be attached to somebody\n--     else's deal if you knew its id.\n--  3. The database itself refuses oversized or malformed input, whatever sent it.\n--  4. A version marker so the app can tell when the database is behind.\n\n-- 1. Privileges -------------------------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['people', 'transactions', 'tasks', 'documents', 'email_drafts', 'settings', 'templates']\n  loop\n    execute format('revoke all on public.%I from anon, public', t);\n    execute format('revoke all on public.%I from authenticated', t);\n    execute format('grant select, insert, update, delete on public.%I to authenticated', t);\n  end loop;\nend $$;\nalter default privileges in schema public revoke all on tables from anon;\n\n-- 2. Same-account references --------------------------------------------------\n-- A unique (id, user_id) pair lets other tables point at \"this record, owned by\n-- this same account\" in one step.\ncreate unique index if not exists people_id_user_key       on public.people (id, user_id);\ncreate unique index if not exists transactions_id_user_key on public.transactions (id, user_id);\n\nalter table public.transactions drop constraint if exists transactions_client_id_fkey;\nalter table public.transactions drop constraint if exists transactions_agent_id_fkey;\nalter table public.transactions drop constraint if exists transactions_client_same_account;\nalter table public.transactions drop constraint if exists transactions_agent_same_account;\nalter table public.transactions add constraint transactions_client_same_account\n  foreign key (client_id, user_id) references public.people (id, user_id);\nalter table public.transactions add constraint transactions_agent_same_account\n  foreign key (agent_id, user_id) references public.people (id, user_id);\n\nalter table public.tasks drop constraint if exists tasks_transaction_id_fkey;\nalter table public.tasks drop constraint if exists tasks_transaction_same_account;\nalter table public.tasks add constraint tasks_transaction_same_account\n  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;\n\nalter table public.documents drop constraint if exists documents_transaction_id_fkey;\nalter table public.documents drop constraint if exists documents_transaction_same_account;\nalter table public.documents add constraint documents_transaction_same_account\n  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;\n\nalter table public.email_drafts drop constraint if exists email_drafts_transaction_id_fkey;\nalter table public.email_drafts drop constraint if exists email_drafts_recipient_id_fkey;\nalter table public.email_drafts drop constraint if exists email_drafts_transaction_same_account;\nalter table public.email_drafts drop constraint if exists email_drafts_recipient_same_account;\nalter table public.email_drafts add constraint email_drafts_transaction_same_account\n  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;\n-- recipient_id may be empty (an AI draft to a typed address); a filled one must be the same account's contact.\nalter table public.email_drafts add constraint email_drafts_recipient_same_account\n  foreign key (recipient_id, user_id) references public.people (id, user_id);\n\n-- 3. Input limits -------------------------------------------------------------\n-- \"not valid\" means: enforced for every new or changed row, without failing on\n-- rows that already exist.\nalter table public.people drop constraint if exists people_input_ck;\nalter table public.people add constraint people_input_ck check (\n  char_length(btrim(name)) between 1 and 200\n  and char_length(phone) <= 50\n  and (email = '' or (char_length(email) <= 320 and email ~ '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$'))\n) not valid;\n\nalter table public.transactions drop constraint if exists transactions_input_ck;\nalter table public.transactions add constraint transactions_input_ck check (\n  char_length(btrim(property_address)) between 1 and 300\n  and char_length(notes) <= 10000\n  and (price is null or (price >= 0 and price < 1000000000000))\n) not valid;\n\nalter table public.tasks drop constraint if exists tasks_input_ck;\nalter table public.tasks add constraint tasks_input_ck check (\n  char_length(btrim(title)) between 1 and 300\n  and (category is null or char_length(category) <= 100)\n  and (key is null or char_length(key) <= 100)\n) not valid;\n\nalter table public.documents drop constraint if exists documents_input_ck;\nalter table public.documents add constraint documents_input_ck check (\n  char_length(btrim(name)) between 1 and 300\n) not valid;\n\nalter table public.email_drafts drop constraint if exists email_drafts_input_ck;\nalter table public.email_drafts add constraint email_drafts_input_ck check (\n  char_length(subject) <= 500\n  and char_length(body) <= 40000\n  and (recipient_email is null or recipient_email = ''\n       or (char_length(recipient_email) <= 320 and recipient_email ~ '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$'))\n  and (ai_info is null or octet_length(ai_info::text) <= 100000)\n) not valid;\n\nalter table public.settings drop constraint if exists settings_input_ck;\nalter table public.settings add constraint settings_input_ck check (\n  char_length(name) <= 200 and char_length(title) <= 200 and char_length(company) <= 200\n  and follow_up_days between 1 and 365\n  and (task_categories is null or octet_length(task_categories::text) <= 20000)\n) not valid;\n\nalter table public.templates drop constraint if exists templates_input_ck;\nalter table public.templates add constraint templates_input_ck check (\n  octet_length(checklists::text) <= 200000 and octet_length(emails::text) <= 200000\n) not valid;\n\n-- 4. Version marker -------------------------------------------------------------\ncreate table if not exists public.app_schema_version (\n  version    integer primary key,\n  applied_at timestamptz not null default now()\n);\ninsert into public.app_schema_version (version) values (1), (2) on conflict do nothing;\nalter table public.app_schema_version enable row level security;\ndrop policy if exists \"read version\" on public.app_schema_version;\ncreate policy \"read version\" on public.app_schema_version for select to authenticated using (true);\nrevoke all on public.app_schema_version from anon, public, authenticated;\ngrant select on public.app_schema_version to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ===== 0003_document_files.sql =====\n-- 0003: file uploads for deals. Safe to run more than once.\n--\n--  * A private storage bucket, \"deal-documents\" (nothing is public).\n--  * A table that records each uploaded file and which deal / checklist document it belongs to.\n--  * Locks: you can only see, add or delete files whose first folder is YOUR user id, and\n--    only into a deal you own. Files are never edited in place.\n--\n-- File paths look like  <user id>/<deal id>/<random>-<file name>\n\n-- 1. The record of each file ---------------------------------------------------\ncreate unique index if not exists documents_id_user_key on public.documents (id, user_id);\n\ncreate table if not exists public.document_files (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,\n  transaction_id uuid not null,\n  document_id    uuid,\n  file_name      text not null,\n  mime_type      text not null,\n  size_bytes     bigint not null,\n  storage_path   text not null unique,\n  created_at     timestamptz not null default now()\n);\n\nalter table public.document_files drop constraint if exists document_files_transaction_same_account;\nalter table public.document_files add constraint document_files_transaction_same_account\n  foreign key (transaction_id, user_id) references public.transactions (id, user_id) on delete cascade;\n-- If the checklist item is deleted the file stays on the deal.\nalter table public.document_files drop constraint if exists document_files_document_same_account;\nalter table public.document_files add constraint document_files_document_same_account\n  foreign key (document_id, user_id) references public.documents (id, user_id) on delete set null (document_id);\n\nalter table public.document_files drop constraint if exists document_files_input_ck;\nalter table public.document_files add constraint document_files_input_ck check (\n  char_length(btrim(file_name)) between 1 and 200\n  and file_name !~ '[/\\\\[:cntrl:]]'\n  and size_bytes between 1 and 10485760\n  and mime_type in (\n    'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/heic',\n    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',\n    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',\n    'text/plain', 'text/csv'\n  )\n  and char_length(storage_path) <= 400\n  and storage_path not like '%..%'\n  and storage_path like user_id::text || '/' || transaction_id::text || '/%'\n);\n\ncreate index if not exists document_files_transaction_idx on public.document_files (transaction_id);\n\nalter table public.document_files enable row level security;\ndrop policy if exists \"own rows\" on public.document_files;\ncreate policy \"own rows\" on public.document_files for all to authenticated\n  using (user_id = (select auth.uid()))\n  with check (user_id = (select auth.uid()));\nrevoke all on public.document_files from anon, public, authenticated;\ngrant select, insert, update, delete on public.document_files to authenticated;\n\n-- 2. The private bucket ---------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  'deal-documents', 'deal-documents', false, 10485760,\n  array[\n    'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/heic',\n    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',\n    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',\n    'text/plain', 'text/csv'\n  ]\n)\non conflict (id) do update\n  set public = false,\n      file_size_limit = excluded.file_size_limit,\n      allowed_mime_types = excluded.allowed_mime_types;\n\n-- 3. The locks on the files themselves ------------------------------------------\n-- No UPDATE policy on purpose: a stored file is never changed, only added or removed.\ndrop policy if exists \"deal files: read own\" on storage.objects;\ncreate policy \"deal files: read own\" on storage.objects for select to authenticated\n  using (bucket_id = 'deal-documents' and (storage.foldername(name))[1] = (select auth.uid())::text);\n\ndrop policy if exists \"deal files: add to own deals\" on storage.objects;\ncreate policy \"deal files: add to own deals\" on storage.objects for insert to authenticated\n  with check (\n    bucket_id = 'deal-documents'\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n    and exists (\n      select 1 from public.transactions t\n      where t.id::text = (storage.foldername(name))[2] and t.user_id = (select auth.uid())\n    )\n  );\n\ndrop policy if exists \"deal files: delete own\" on storage.objects;\ncreate policy \"deal files: delete own\" on storage.objects for delete to authenticated\n  using (bucket_id = 'deal-documents' and (storage.foldername(name))[1] = (select auth.uid())::text);\n\n-- 4. Version marker ----------------------------------------------------------------\ninsert into public.app_schema_version (version) values (3) on conflict do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ===== 0004_daily_reminders.sql =====\n-- 0004: daily reminder emails. Safe to run more than once.\n--\n-- A scheduled job INSIDE Supabase (see supabase/reminders-schedule.sql) emails each\n-- person who switched reminders on a plain-text list of what is overdue or coming up.\n--\n--  * Only ever sent to the account's own login email, never to an address typed in.\n--  * The email service key lives in Supabase Vault, not in the app.\n--  * The sending functions are not callable by logged-in users or visitors, except\n--    send_test_reminder(), which can only email YOU and is rate limited.\n\n-- 1. Your choices (these are yours to change) ---------------------------------------\nalter table public.settings add column if not exists reminders_enabled boolean not null default false;\nalter table public.settings add column if not exists reminder_hour smallint not null default 8;\nalter table public.settings add column if not exists reminder_timezone text not null default 'America/New_York';\n\nalter table public.settings drop constraint if exists settings_reminder_ck;\nalter table public.settings add constraint settings_reminder_ck check (\n  reminder_hour between 0 and 23 and char_length(reminder_timezone) between 1 and 64\n);\n\n-- 2. Bookkeeping and setup nobody but the server can touch ----------------------------\ncreate table if not exists public.reminder_state (\n  user_id    uuid primary key references auth.users (id) on delete cascade,\n  last_sent  date,\n  test_at    timestamptz,\n  test_day   date,\n  test_count integer not null default 0\n);\ncreate table if not exists public.reminder_config (\n  id           integer primary key check (id = 1),\n  app_url      text,\n  from_address text\n);\n-- Row level security on with no policies = nobody (except the server) can read or write.\nalter table public.reminder_state enable row level security;\nalter table public.reminder_config enable row level security;\nrevoke all on public.reminder_state from anon, public, authenticated;\nrevoke all on public.reminder_config from anon, public, authenticated;\n\n-- 3. The work, in a schema the API does not expose -------------------------------------\ncreate schema if not exists app_private;\nrevoke all on schema app_private from public, anon, authenticated;\n\n-- What is overdue or coming up for one person. Mirrors the follow-ups page:\n-- open tasks, documents not yet received, and closing dates, on deals that are\n-- not archived and are active or pending. Returns null when there is nothing.\ncreate or replace function app_private.reminder_digest(p_user uuid, p_today date)\nreturns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$\ndeclare\n  win int; cutoff date; r record; days int; label text;\n  over_lines text[] := '{}'; soon_lines text[] := '{}'; n_over int := 0; n_soon int := 0;\n  cfg_url text; body text;\nbegin\n  select coalesce(follow_up_days, 7) into win from settings where user_id = p_user;\n  win := coalesce(win, 7);\n  cutoff := p_today + win;\n\n  for r in\n    select x.deal, x.title, x.due from (\n      select t.property_address as deal, k.title, k.due\n      from transactions t\n      cross join lateral (\n        select title, due_date as due from tasks\n          where transaction_id = t.id and user_id = p_user and status = 'open' and due_date is not null and due_date <= cutoff\n        union all\n        select name, due_date from documents\n          where transaction_id = t.id and user_id = p_user and status <> 'received' and due_date is not null and due_date <= cutoff\n        union all\n        select 'Closing date', t.closing_date where t.closing_date is not null and t.closing_date <= cutoff\n      ) k\n      where t.user_id = p_user and not t.archived and t.status in ('active', 'pending')\n    ) x order by x.due, x.deal, x.title\n  loop\n    days := r.due - p_today;\n    label := case when days < 0 then (-days) || case when days = -1 then ' day overdue' else ' days overdue' end\n                  when days = 0 then 'due today'\n                  else 'due in ' || days || case when days = 1 then ' day' else ' days' end end;\n    if days < 0 then\n      n_over := n_over + 1;\n      if n_over <= 25 then over_lines := over_lines || format('  - %s: %s (%s)', left(regexp_replace(r.deal, '\\s+', ' ', 'g'), 80), left(regexp_replace(r.title, '\\s+', ' ', 'g'), 120), label); end if;\n    else\n      n_soon := n_soon + 1;\n      if n_soon <= 25 then soon_lines := soon_lines || format('  - %s: %s (%s)', left(regexp_replace(r.deal, '\\s+', ' ', 'g'), 80), left(regexp_replace(r.title, '\\s+', ' ', 'g'), 120), label); end if;\n    end if;\n  end loop;\n\n  if n_over + n_soon = 0 then return null; end if;\n\n  select app_url into cfg_url from reminder_config where id = 1;\n  body := format('You have %s overdue and %s coming up in the next %s days.', n_over, n_soon, win) || E'\\n';\n  if n_over > 0 then\n    body := body || E'\\nOVERDUE (' || n_over || E')\\n' || array_to_string(over_lines, E'\\n') || E'\\n';\n    if n_over > 25 then body := body || format('  ...and %s more', n_over - 25) || E'\\n'; end if;\n  end if;\n  if n_soon > 0 then\n    body := body || E'\\nCOMING UP (' || n_soon || E')\\n' || array_to_string(soon_lines, E'\\n') || E'\\n';\n    if n_soon > 25 then body := body || format('  ...and %s more', n_soon - 25) || E'\\n'; end if;\n  end if;\n  if coalesce(cfg_url, '') <> '' then\n    body := body || E'\\nOpen TC Assistant: ' || cfg_url || E'/follow-ups\\nTurn these emails off in Settings: ' || cfg_url || E'/settings\\n';\n  end if;\n  return jsonb_build_object('overdue', n_over, 'soon', n_soon, 'text', body);\nend $$;\n\n-- Sends one email to the account's own login address. Returns 'sent', 'empty' or 'unconfigured'.\ncreate or replace function app_private.deliver_reminder(p_user uuid, p_today date, p_send_empty boolean)\nreturns text language plpgsql security definer set search_path = public, pg_temp as $$\ndeclare digest jsonb; to_email text; api_key text; sender text; subject text; body text;\nbegin\n  digest := app_private.reminder_digest(p_user, p_today);\n  if digest is null and not p_send_empty then return 'empty'; end if;\n\n  select email into to_email from auth.users where id = p_user;\n  select decrypted_secret into api_key from vault.decrypted_secrets where name = 'resend_api_key' limit 1;\n  select from_address into sender from reminder_config where id = 1;\n  if coalesce(to_email, '') = '' or coalesce(api_key, '') = '' or coalesce(sender, '') = '' then\n    raise warning 'reminders: not set up yet (need the Resend key in Vault and a from address in reminder_config)';\n    return 'unconfigured';\n  end if;\n\n  if digest is null then\n    subject := 'TC Assistant: nothing is due';\n    body := 'Test email from TC Assistant. Nothing is overdue or coming up right now, so a real reminder would be skipped today.';\n  else\n    subject := format('TC Assistant: %s overdue, %s coming up', digest->>'overdue', digest->>'soon');\n    body := digest->>'text';\n  end if;\n\n  perform net.http_post(\n    url := 'https://api.resend.com/emails',\n    headers := jsonb_build_object('Authorization', 'Bearer ' || api_key, 'Content-Type', 'application/json'),\n    body := jsonb_build_object('from', sender, 'to', jsonb_build_array(to_email), 'subject', subject, 'text', body)\n  );\n  return 'sent';\nend $$;\n\n-- Called by the hourly schedule. Sends to everyone whose chosen hour it is right now\n-- (in their own time zone) who has not already had today's email.\ncreate or replace function app_private.send_due_reminders(p_now timestamptz default now())\nreturns integer language plpgsql security definer set search_path = public, pg_temp as $$\ndeclare r record; local_ts timestamp; local_day date; outcome text; sent int := 0;\nbegin\n  for r in select user_id, reminder_hour, reminder_timezone from settings where reminders_enabled loop\n    begin\n      local_ts := p_now at time zone r.reminder_timezone;\n      continue when extract(hour from local_ts)::int <> r.reminder_hour;\n      local_day := local_ts::date;\n      continue when exists (select 1 from reminder_state where user_id = r.user_id and last_sent = local_day);\n\n      outcome := app_private.deliver_reminder(r.user_id, local_day, false);\n      if outcome in ('sent', 'empty') then\n        insert into reminder_state (user_id, last_sent) values (r.user_id, local_day)\n          on conflict (user_id) do update set last_sent = excluded.last_sent;\n      end if;\n      if outcome = 'sent' then sent := sent + 1; end if;\n    exception when others then\n      raise warning 'reminders: skipped one account (%)', sqlerrm;\n    end;\n  end loop;\n  return sent;\nend $$;\n\nrevoke all on function app_private.reminder_digest(uuid, date) from public, anon, authenticated;\nrevoke all on function app_private.deliver_reminder(uuid, date, boolean) from public, anon, authenticated;\nrevoke all on function app_private.send_due_reminders(timestamptz) from public, anon, authenticated;\n\n-- 4. The \"Send me a test email\" button ---------------------------------------------------\n-- Takes no arguments: it can only ever email the person who is logged in.\ncreate or replace function public.send_test_reminder()\nreturns text language plpgsql security definer set search_path = public, pg_temp as $$\ndeclare uid uuid := auth.uid(); st record; tz text; today date;\nbegin\n  if uid is null then raise exception 'Please log in first.' using errcode = '28000'; end if;\n  insert into reminder_state (user_id) values (uid) on conflict (user_id) do nothing;\n  select * into st from reminder_state where user_id = uid for update;\n  if st.test_at is not null and st.test_at > now() - interval '2 minutes' then\n    raise exception 'Please wait a couple of minutes before sending another test.';\n  end if;\n  if st.test_day = current_date and st.test_count >= 5 then\n    raise exception 'That is enough test emails for today. Try again tomorrow.';\n  end if;\n  update reminder_state\n     set test_at = now(), test_day = current_date,\n         test_count = case when test_day = current_date then test_count + 1 else 1 end\n   where user_id = uid;\n  select reminder_timezone into tz from settings where user_id = uid;\n  begin\n    today := (now() at time zone coalesce(tz, 'America/New_York'))::date;\n  exception when others then\n    today := current_date;\n  end;\n  return app_private.deliver_reminder(uid, today, true);\nend $$;\n\nrevoke all on function public.send_test_reminder() from public, anon;\ngrant execute on function public.send_test_reminder() to authenticated;\n\n-- 5. Version marker -----------------------------------------------------------------------\ninsert into public.app_schema_version (version) values (4) on conflict do nothing;\n\nnotify pgrst, 'reload schema';\n";
